import sys


def main():
    group_of = {}
    groups = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        names = line.split()
        if len(names) == 1:
            name = names[0]
            if name not in group_of:
                group_of[name] = len(groups)
                groups.append(set())
        else:
            first_name = names[0]
            last_name = names[-1]
            if first_name in group_of:
                group = group_of[first_name]
            elif last_name in group_of:
                group = group_of[last_name]
            else:
                group = len(groups)
                groups.append(set())
            for name in names:
                group_of[name] = group
                groups[group].add(name)
    groups.sort(key=lambda s: (-len(s), min(s)))
    for group in groups:
        print(" ".join(sorted(group)))


if __name__ == "__main__":
    main()
